// ExecParams（exec.rs:83）
ExecParams {
  command: ["cargo", "check"],
  cwd: /home/user/myproject,
  expiration: ExecExpiration::DefaultTimeout,
  // DEFAULT_EXEC_COMMAND_TIMEOUT_MS = 10_000
  capture_policy: ExecCapturePolicy::ShellTool,
  env: { PATH: /usr/bin:... },
  network: None,
  sandbox_permissions: SandboxPermissions::UseDefault,
}

// exec.rs:131 — 沙箱类型选择
fn select_process_exec_tool_sandbox_type(
  file_system_sandbox_policy,
  network_sandbox_policy,
  windows_sandbox_level,
  enforce_managed_network,
) -> SandboxType

// Linux:   → SandboxType::Landlock
// macOS:   → SandboxType::Seatbelt
// Windows: → SandboxType::WindowsRestrictedToken
//             或 WindowsElevated（proxy_enforced 时）

// exec.rs:245 — build_exec_request()
// 将 ExecParams → ExecRequest（含平台相关字段）
ExecRequest {
  command: ["cargo", "check"],
  cwd: /home/user/myproject,
  env: { PATH: ..., CARGO_HOME: ... },
  sandbox: SandboxType::Landlock,
  expiration: ExecExpiration::DefaultTimeout,
  capture_policy: ExecCapturePolicy::ShellTool,
  ...
}

// exec.rs:877 — spawn_child_async()
spawn_child_async(SpawnChildRequest {
  program: PathBuf::from("cargo"),
  args: ["check"],
  cwd: /home/user/myproject,
  stdio_policy: StdioPolicy::RedirectForShellTool,
  // → stdout: Stdio::piped()
  // → stderr: Stdio::piped()
  env: { ... },
  network_sandbox_policy: NetworkSandboxPolicy,
  network: None,
}).await?
// → Child { pid: 18372 } 沙箱内运行

// exec.rs:1234 — consume_output() 启动三路并行
async fn consume_output(
  child: Child,
  expiration: ExecExpiration,
  capture_policy: ExecCapturePolicy,
  stdout_stream: Option<StdoutStream>,
) -> Result<RawExecToolCallOutput>

// 三路并行：
tokio::spawn(read_capped(stdout_reader, ...))  // stdout 任务
tokio::spawn(read_capped(stderr_reader, ...))  // stderr 任务
// tokio::select! {
//   result = child.wait()      => 进程正常退出
//   _ = expiration.wait()      => 超时触发
//   _ = ctrl_c_signal          => 用户中止
// }

// tokio::select! 竞争结果：child.wait() 先触发
// exit_status = ExitStatus(0)
// timed_out = false

// 等待 pipe reader task 完成
// IO_DRAIN_TIMEOUT_MS = 2_000（exec.rs:80）
stdout_handle.await  // ✓ 完成
stderr_handle.await  // ✓ 完成
// 防止孙进程持有 fd 导致 read() 永久阻塞

// 超时分支示例（timed_out = true）
// expiration.wait() 先于 child.wait() 触发：
kill_child_process_group(child.id())
// → SIGKILL 发送给整个进程组（含孙进程）

// exec.rs:57
const EXEC_TIMEOUT_EXIT_CODE: i32 = 124;
// finalize_exec_result() 将 exit_code 覆盖为 124

// exec.rs:640 — finalize_exec_result()
ExecToolCallOutput {
  exit_code: 0,
  stdout: StreamOutput {
    text: "   Compiling myapp v0.1.0\n    Finished dev in 2.34s",
    truncated_after_lines: None,
  },
  stderr: StreamOutput { text: "", .. },
  aggregated_output: StreamOutput { .. },
  duration: 2.341s,
  timed_out: false,
}
// → ResponseInputItem::FunctionCallOutput
// → record_conversation_items() → session history
